wire [32:0] memory_fetch_end={1'b0,memory_command_offset}+{19'd0,memory_command_length};
// Parallel byte comparisons replace the serial full-width magnitude chain.
// The original relational expression remains the four-state fallback.
wire [34:0] fetch_range_left={2'd0,memory_fetch_end};
wire [34:0] fetch_range_right={1'b0,memory_committed,2'b0};
wire [4:0] fetch_range_greater,fetch_range_equal;
assign fetch_range_greater[0]=fetch_range_left[7:0]>fetch_range_right[7:0];
assign fetch_range_equal[0]=fetch_range_left[7:0]==fetch_range_right[7:0];
assign fetch_range_greater[1]=fetch_range_left[15:8]>fetch_range_right[15:8];
assign fetch_range_equal[1]=fetch_range_left[15:8]==fetch_range_right[15:8];
assign fetch_range_greater[2]=fetch_range_left[23:16]>fetch_range_right[23:16];
assign fetch_range_equal[2]=fetch_range_left[23:16]==fetch_range_right[23:16];
assign fetch_range_greater[3]=fetch_range_left[31:24]>fetch_range_right[31:24];
assign fetch_range_equal[3]=fetch_range_left[31:24]==fetch_range_right[31:24];
assign fetch_range_greater[4]=fetch_range_left[34:32]>fetch_range_right[34:32];
assign fetch_range_equal[4]=fetch_range_left[34:32]==fetch_range_right[34:32];
reg memory_fetch_range_bad;
always @* begin
    memory_fetch_range_bad={2'd0,memory_fetch_end}>{1'b0,memory_committed,2'b0};
    case (^{fetch_range_left,fetch_range_right})
        1'b0,1'b1: memory_fetch_range_bad=(fetch_range_greater[4] || (fetch_range_equal[4] && (fetch_range_greater[3] || (fetch_range_equal[3] && (fetch_range_greater[2] || (fetch_range_equal[2] && (fetch_range_greater[1] || (fetch_range_equal[1] && fetch_range_greater[0]))))))));
        default: begin end
    endcase
end

(* syn_preserve=1 *) reg [79+PTR_BITS:0] payload;
reg [32:0] fetch_end;
assign memory_fetch_end=fetch_end;
